SELECT brand_id, brand_name, brand_logo, description, sort, status, update_time, create_time FROM t_brand
deleted_flag = 0
AND brand_name LIKE CONCAT('%', #{queryForm.keyword}, '%')
AND status = #{queryForm.status}
AND deleted_flag = #{queryForm.deletedFlag}
ORDER BY sort ASC, create_time DESC

SELECT * FROM t_brand
WHERE brand_name = #{brandName}
AND deleted_flag = 0

    AND brand_id != #{excludeBrandId}

LIMIT 1
